// CSS: main.src.css (list of @imports) → main.css as a single, minified file.
// An @import chains requests (HTML → main.css → partials) before painting.

import fs from 'node:fs';
import path from 'node:path';
import { fail } from './site.mjs';

const BANNER = '/* GENERATED by scripts/build-i18n.mjs from assets/css/main.src.css — do not edit */';

/** Content of main.css: every `@import url('./partial.css')` of main.src.css inlined, then minified */
export function bundleCss(cssDir) {
  const src = fs.readFileSync(path.join(cssDir, 'main.src.css'), 'utf8');
  const bundled = src
    // commented-out @imports are left out
    .replace(/\/\*\s*@import[^*]*\*\/\n?/g, '')
    .replace(/@import url\(['"]?\.\/([^'")]+)['"]?\);?/g, (_, file) => {
      const css = fs.readFileSync(path.join(cssDir, file), 'utf8').trim();
      return `${css}\n`;
    });
  if (/^\s*@import/m.test(bundled)) fail('main.src.css: an @import was left unresolved');
  return `${BANNER}\n${minifyCss(bundled)}\n`;
}

// ---------------------------------------------------------------------------
// Conservative minifier: it only removes what is provably insignificant, so
// the browser parses the result into exactly the same rules (checked by
// comparing the CSSOM serialisation of every rule and declaration of the
// unminified and the minified bundle in Chromium).
// - comments are dropped;
// - strings, url(…), custom property values (--x: …) and values that use
//   var()/env()/attr() are copied verbatim, only trimmed (the browser keeps
//   those as written until they are computed);
// - every other run of whitespace becomes one space, and that space is dropped
//   next to { } ; , and after : (never before : — `a :hover` is a descendant
//   combinator — nor around + - * / > ~, which calc() and selectors need);
//   inside at-rule preludes (@media, @supports…, kept as written by the
//   browser) only next to { } ;
// - the `;` before a `}` is dropped.

const isSpace = (c) => c === ' ' || c === '\n' || c === '\t' || c === '\r' || c === '\f';
const isIdent = (c) => c !== undefined && /[\w\u0080-￿-]/.test(c);
// No space is needed between these and the next token
const NO_SPACE_AFTER = new Set(['{', '}', ';', ',', ':']);
const NO_SPACE_BEFORE = new Set(['{', '}', ';', ',']);
const BLOCK_EDGES = new Set(['{', '}', ';']);
// Values the browser stores unparsed (pending substitution): kept as written
const UNPARSED_VALUE = /\b(?:var|env|attr)\(/i;

/** Index just past the string that starts at `i` (quote at css[i]) */
function stringEnd(css, i) {
  const quote = css[i];
  let j = i + 1;
  while (j < css.length && css[j] !== quote) {
    if (css[j] === '\\') j++;
    else if (css[j] === '\n') fail('css-bundle: unterminated string');
    j++;
  }
  if (j >= css.length) fail('css-bundle: unterminated string');
  return j + 1;
}

/** Index just past the comment that starts at `i` */
function commentEnd(css, i) {
  const end = css.indexOf('*/', i + 2);
  if (end === -1) fail('css-bundle: unterminated comment');
  return end + 2;
}

/**
 * End of a declaration value that starts at `i`: the `;`, `}` or the
 * unbalanced `)` (style() queries) at nesting depth 0, skipping strings and
 * comments. With `selectorStop`, a `{` at depth 0 also ends it (then what
 * looked like `property: value` was the selector of a nested rule, `a:hover {`).
 */
function valueEnd(css, i, selectorStop = false) {
  let depth = 0;
  let j = i;
  while (j < css.length) {
    const c = css[j];
    if (c === '"' || c === "'") {
      j = stringEnd(css, j);
      continue;
    }
    if (c === '/' && css[j + 1] === '*') {
      j = commentEnd(css, j);
      continue;
    }
    if (c === '{' && depth === 0 && selectorStop) return j;
    if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') {
      if (depth === 0) return j;
      depth--;
    } else if (c === ';' && depth === 0) return j;
    j++;
  }
  return j;
}

export function minifyCss(css) {
  let out = '';
  let pendingSpace = false;
  let inPrelude = false; // between an at-rule's name and its { or ;
  const last = () => out[out.length - 1];

  // Writes a token, deciding first whether the whitespace before it is needed
  const emit = (token) => {
    if (pendingSpace && out) {
      const needed = inPrelude
        ? !BLOCK_EDGES.has(last()) && !BLOCK_EDGES.has(token[0])
        : !NO_SPACE_AFTER.has(last()) && !NO_SPACE_BEFORE.has(token[0]);
      if (needed) out += ' ';
    }
    pendingSpace = false;
    if (token === '}' && last() === ';') out = out.slice(0, -1);
    if (token === '@') inPrelude = true;
    else if (BLOCK_EDGES.has(token)) inPrelude = false;
    out += token;
  };

  // `name: value` at the start of a declaration whose value is kept as written
  // (custom property, or a value using var()…): emits it and returns the index
  // just past the value; otherwise returns -1
  const verbatimDeclaration = (start, nameEnd, custom) => {
    let k = nameEnd;
    while (isSpace(css[k])) k++;
    if (css[k] !== ':') return -1;
    const end = valueEnd(css, k + 1, !custom);
    if (css[end] === '{') return -1; // a nested rule's selector
    const value = css.slice(k + 1, end).trim();
    if (!custom && !UNPARSED_VALUE.test(value)) return -1;
    emit(css.slice(start, nameEnd));
    emit(':');
    if (value) emit(value);
    return end;
  };

  let i = 0;
  while (i < css.length) {
    const c = css[i];

    if (c === '/' && css[i + 1] === '*') {
      const end = commentEnd(css, i);
      // `a/**/b` is two tokens: dropping the comment would merge them
      if (isIdent(last()) && !pendingSpace && isIdent(css[end])) fail('css-bundle: comment between two identifiers');
      i = end;
      continue;
    }

    if (isSpace(c)) {
      pendingSpace = true;
      i++;
      continue;
    }

    if (c === '"' || c === "'") {
      const end = stringEnd(css, i);
      emit(css.slice(i, end));
      i = end;
      continue;
    }

    // Unquoted url(…): verbatim up to the closing parenthesis
    if ((c === 'u' || c === 'U') && /^url\(/i.test(css.slice(i, i + 4)) && !isIdent(css[i - 1])) {
      let j = i + 4;
      while (isSpace(css[j])) j++;
      if (css[j] !== '"' && css[j] !== "'") {
        const end = css.indexOf(')', j);
        if (end === -1) fail('css-bundle: unterminated url(');
        emit(css.slice(i, end + 1));
        i = end + 1;
        continue;
      }
    }

    // Custom property declaration (--name: value): the value is kept as written
    if (c === '-' && css[i + 1] === '-' && !isIdent(css[i - 1])) {
      let j = i + 2;
      while (isIdent(css[j]) || css[j] === '\\') j += css[j] === '\\' ? 2 : 1;
      const end = verbatimDeclaration(i, j, true);
      if (end === -1) emit(css.slice(i, j));
      i = end === -1 ? j : end;
      continue;
    }

    // Identifiers and numbers in one piece, every other character on its own
    if (isIdent(c)) {
      let j = i + 1;
      while (isIdent(css[j])) j++;
      // A property name (declarations start after { or ;, or after a nested
      // rule's }; a selector there is told apart by the { that ends it)
      const end = !inPrelude && BLOCK_EDGES.has(last()) ? verbatimDeclaration(i, j, false) : -1;
      if (end === -1) emit(css.slice(i, j));
      i = end === -1 ? j : end;
      continue;
    }
    if (c === '\\') {
      emit(css.slice(i, i + 2));
      i += 2;
      continue;
    }
    emit(c);
    i++;
  }
  return out.trim();
}
